// app/dashboard/page.tsx — Server Component (default)
async function DashboardPage() {
  const metrics = await fetchMetrics(); // direct DB access, no API route
  const recent = await fetchRecentOrders();

  return (
    <section>
      <h1>Dashboard</h1>
      {/* Server-rendered static summary */}
      <MetricsGrid metrics={metrics} />
      {/* Interactive controls live in client boundary */}
      <OrderFilters initialOrders={recent} />
    </section>
  );
}

// app/dashboard/OrderFilters.tsx — Client Component
'use client';
import { useState } from 'react';

function OrderFilters({ initialOrders }: { initialOrders: Order[] }) {
  const [filter, setFilter] = useState('');
  const [sort, setSort] = useState<'asc' | 'desc'>('desc');
  // filtering and sorting happen client-side
  const visible = initialOrders
    .filter(o => o.status.includes(filter))
    .sort((a, b) => sort === 'asc'
      ? a.createdAt.localeCompare(b.createdAt)
      : b.createdAt.localeCompare(a.createdAt));

  return (
    <div>
      <input onChange={e => setFilter(e.target.value)} />
      <select value={sort} onChange={e => setSort(e.target.value as any)}>
        <option value="desc">Newest</option>
        <option value="asc">Oldest</option>
      </select>
      <OrderTable orders={visible} />
    </div>
  );
}
